SELECT jepmcd, jepmnm, makecust, brand, jpmkind, price, setchk, chk, oldbar, remk, prdate, moddate, shopno FROM jepm_all where chk = 'Y'
AND BRAND like #{brand}
AND jepmnm like #{jepmnm}
AND price = #{price}
order by brand,jepmnm

SELECT memno, name, birthday, member, addr, handno, hand4, saleamt, misuamt, bonusamt, visitcnt, prdate, remk, daygubun, shopno, memno6, lastdate, manager FROM member where chk = 'Y' and sys = 'N'
AND name like #{name}
AND handno = #{handno}
AND hand4 = #{hand4}
order by name

